INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, difficulty_level, difficulty_basis, sources, last_checked)
SELECT id, 'product_manager', 'all levels', '[{"name": "Hiring assessment", "format": "Optional timed workstyle survey of situational questions", "tests": "Collaboration, communication and handling ambiguity", "duration": "About 30 minutes"}, {"name": "Recruiter screen", "format": "Call", "tests": "Background, motivation and behavioural questions", "duration": "30 minutes"}, {"name": "Product sense screen", "format": "Structured product case led by a senior PM", "tests": "Structured reasoning, prioritisation, trade-offs and metrics", "duration": "45 minutes"}, {"name": "Onsite loop", "format": "Four to five interviews, virtual or in person", "tests": "Product design, analytical thinking and execution, product strategy, and leadership and Googleyness", "duration": "About 45 minutes each"}, {"name": "Team matching and hiring committee", "format": "Four to eight team conversations, then a committee", "tests": "Fit with teams and the level decision", "duration": null}]'::jsonb, '[]'::jsonb, NULL, 'The guide describes four to six weeks from application to the final round, with team matching one to two months after the onsite and sometimes longer. It is titled 2026 and does not rate difficulty.', NULL, NULL, NULL, '[{"url": "https://www.aced.io/guides/google-product-manager-interview", "title": "Google product manager interview guide (aced.io, 2026)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'google';

